namespace {
bool safe(const std::string&s){if(s.empty()||s.size()>700||s.front()=='/'||s.back()=='/'||s.find_first_of("\\:\r\n\t")!=std::string::npos||s.find('\0')!=std::string::npos)return false;std::istringstream in(s);std::string part;while(std::getline(in,part,'/'))if(part.empty()||part=="."||part==".."||part.back()=='.'||part.back()==' ')return false;return true;}
std::string unhex(const std::string&s){require(s.size()%2==0&&s.size()<=4096,"Invalid stored field");std::string out;auto nib=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};for(size_t i=0;i<s.size();i+=2){int a=nib(s[i]),b=nib(s[i+1]);require(a>=0&&b>=0,"Invalid stored field");out+=char(a*16+b);}return out;}
std::string encode(const std::string&s){return hex((const u8*)s.data(),s.size());}
struct Row{std::string path,hash;u64 size;};
std::string manifest(const std::vector<Row>&rows){std::string out="GVREMOTE1\n";for(auto&r:rows)out+=std::to_string(r.size)+" "+r.hash+" "+encode(r.path)+"\n";return out;}
std::vector<Row> parse(const std::string&s){require(s.size()<=32*1024*1024,"Remote manifest too large");std::istringstream in(s);std::string magic;std::getline(in,magic);require(magic=="GVREMOTE1","Remote backup format unsupported");std::vector<Row>out;std::set<std::string>names;std::string line;u64 total=0;while(std::getline(in,line)){std::istringstream row(line);std::string n,h,p,extra;require(bool(row>>n>>h>>p)&&!(row>>extra)&&n.size()<=19&&n.find_first_not_of("0123456789")==std::string::npos,"Invalid remote manifest row");Row r{unhex(p),h,std::stoull(n)};require(safe(r.path)&&r.hash.size()==64&&r.hash.find_first_not_of("0123456789abcdef")==std::string::npos&&r.size<=INT64_MAX&&UINT64_MAX-total>=r.size,"Unsafe remote manifest");std::string canonical=r.path;for(char&c:canonical)if(c>='A'&&c<='Z')c+=32;require(names.insert(canonical).second,"Duplicate remote path");total+=r.size;out.push_back(r);require(out.size()<=100000,"Remote entry limit");}require(!out.empty(),"Empty remote backup");for(auto&r:out)for(size_t at=0;(at=r.path.find('/',at))!=std::string::npos;++at){std::string parent=r.path.substr(0,at);for(char&c:parent)if(c>='A'&&c<='Z')c+=32;require(!names.count(parent),"Remote file/directory collision");}return out;}
struct CurlState{FILE*file=nullptr;std::string text;size_t limit=0;Sha256Context hash;u64 count=0,max=UINT64_MAX;bool digest=false,upload=false;std::string phase,path;bool cancelled=false;};
size_t consume(char*p,size_t a,size_t b,void*v){auto&s=*(CurlState*)v;size_t n=a*b;try{require(n<=s.max-s.count,"Remote file exceeds manifest size");if(s.digest)sha256ContextUpdate(&s.hash,p,n);if(s.file){require(fwrite(p,1,n,s.file)==n,"Local write failed");}else if(!s.digest){require(n<=s.limit-s.text.size(),"Remote response too large");s.text.append(p,n);}s.count+=n;return n;}catch(...){return 0;}}
int progress(void*v,curl_off_t,curl_off_t now,curl_off_t,curl_off_t sent){auto&s=*(CurlState*)v;try{pump();vaultTransfer(s.phase.c_str(),s.path.c_str(),s.upload?sent:now,s.max==UINT64_MAX?0:s.max);return 0;}catch(...){s.cancelled=true;return 1;}}
class Remote {
 RemoteTarget target;CURL*curl=nullptr;smb2_context*smb=nullptr;
 std::string full(const std::string&p){require(p.empty()||safe(p),"Unsafe remote path");return target.path.empty()?p:target.path+(p.empty()?"":"/"+p);}
 std::string url(const std::string&p){std::string escaped;for(unsigned char c:full(p)){if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='/'||c=='-'||c=='_'||c=='.')escaped+=c;else{char b[4];snprintf(b,sizeof(b),"%%%02X",c);escaped+=b;}}return "ftp://"+target.host+":"+std::to_string(target.port)+"/"+escaped;}
 void setup(const std::string&p,CurlState&state){curl_easy_reset(curl);auto u=url(p);curl_easy_setopt(curl,CURLOPT_URL,u.c_str());curl_easy_setopt(curl,CURLOPT_USERNAME,target.user.c_str());curl_easy_setopt(curl,CURLOPT_PASSWORD,target.password.c_str());curl_easy_setopt(curl,CURLOPT_CONNECTTIMEOUT,10L);curl_easy_setopt(curl,CURLOPT_LOW_SPEED_LIMIT,1L);curl_easy_setopt(curl,CURLOPT_LOW_SPEED_TIME,30L);curl_easy_setopt(curl,CURLOPT_NOSIGNAL,1L);curl_easy_setopt(curl,CURLOPT_NOPROGRESS,0L);curl_easy_setopt(curl,CURLOPT_XFERINFOFUNCTION,progress);curl_easy_setopt(curl,CURLOPT_XFERINFODATA,&state);curl_easy_setopt(curl,CURLOPT_WRITEFUNCTION,consume);curl_easy_setopt(curl,CURLOPT_WRITEDATA,&state);curl_easy_setopt(curl,CURLOPT_FTP_SKIP_PASV_IP,1L);}
 void perform(CurlState&s){auto rc=curl_easy_perform(curl);if(s.cancelled)throw std::runtime_error("Cancelled; partial remote backup retained");require(rc==CURLE_OK,"FTP operation failed; check server, credentials and folder");}
public:
 explicit Remote(const RemoteTarget&t):target(t){validateRemoteTarget(t);vaultNetworkAcquire();try{if(t.smb){smb=smb2_init_context();require(smb,"SMB context");smb2_set_timeout(smb,10);smb2_set_password(smb,t.user.empty()&&t.password.empty()?nullptr:t.password.c_str());smb2_set_domain(smb,t.domain.c_str());std::string server=t.host+(t.port==445?"":":"+std::to_string(t.port));int connected=smb2_connect_share(smb,server.c_str(),t.share.c_str(),t.user.c_str());
#ifdef GAMEVAULT_REMOTE_HOST_TEST
if(connected)fprintf(stderr,"SMB connect rc=%d: %s\n",connected,smb2_get_error(smb));
#endif
require(connected==0,"SMB connection failed; check share and credentials");}else{static const auto initialized=curl_global_init(CURL_GLOBAL_DEFAULT);require(initialized==CURLE_OK,"FTP client initialization");curl=curl_easy_init();require(curl,"FTP client");}}catch(...){if(smb)smb2_destroy_context(smb);if(curl)curl_easy_cleanup(curl);vaultNetworkRelease();throw;}}
 ~Remote(){if(smb)smb2_destroy_context(smb);if(curl)curl_easy_cleanup(curl);vaultNetworkRelease();}
 std::vector<std::string> list(const std::string&p){std::vector<std::string>out;if(smb){auto*d=smb2_opendir(smb,full(p).c_str());require(d,"Cannot list SMB folder");try{while(auto*e=smb2_readdir(smb,d)){pump();std::string n=e->name;if(n!="."&&n!=".."&&n.find('/')==std::string::npos&&safe(n))out.push_back(n);require(out.size()<=100000,"Remote folder too large");}smb2_closedir(smb,d);}catch(...){smb2_closedir(smb,d);throw;}}else{CurlState state;state.limit=8*1024*1024;state.phase="Listing FTP storage";setup(p,state);auto u=url(p)+"/";curl_easy_setopt(curl,CURLOPT_URL,u.c_str());curl_easy_setopt(curl,CURLOPT_DIRLISTONLY,1L);perform(state);std::istringstream in(state.text);std::string n;while(std::getline(in,n)){if(!n.empty()&&n.back()=='\r')n.pop_back();auto slash=n.find_last_of('/');if(slash!=std::string::npos)n=n.substr(slash+1);if(safe(n))out.push_back(n);}}return out;}
 void mkdirs(const std::string&p){std::string path=full(p);for(size_t at=0;at<=path.size();++at)if(at==path.size()||path[at]=='/'){auto part=path.substr(0,at);if(part.empty())continue;if(smb){int rc=smb2_mkdir(smb,part.c_str());require(rc==0||rc==-EEXIST,"Create SMB folder failed");}else{CurlState state;setup("",state);auto u="ftp://"+target.host+":"+std::to_string(target.port)+"/";curl_easy_setopt(curl,CURLOPT_URL,u.c_str());auto*commands=curl_slist_append(nullptr,("*MKD /"+part).c_str());curl_easy_setopt(curl,CURLOPT_QUOTE,commands);curl_easy_setopt(curl,CURLOPT_NOBODY,1L);try{perform(state);curl_slist_free_all(commands);}catch(...){curl_slist_free_all(commands);throw;}}}}
 void get(const std::string&p,CurlState&state){state.path=p;state.phase=state.digest?"Verifying remote backup":"Downloading remote backup";if(!smb){setup(p,state);perform(state);return;}auto*f=smb2_open(smb,full(p).c_str(),O_RDONLY);require(f,"Open remote file");std::vector<u8>buf(262144);try{for(;;){pump();int n=smb2_read(smb,f,buf.data(),buf.size());require(n>=0,"Read remote file");if(!n)break;require(consume((char*)buf.data(),1,n,&state)==size_t(n),"Remote read bounds or disk write failed");vaultTransfer(state.phase.c_str(),p.c_str(),state.count,state.max==UINT64_MAX?0:state.max);}int closed=smb2_close(smb,f);f=nullptr;require(closed==0,"Close remote file");}catch(...){if(f)smb2_close(smb,f);throw;}}
 std::string text(const std::string&p,size_t limit){CurlState state;state.limit=limit;get(p,state);return state.text;}
 void put(const std::string&local,const std::string&p,u64 size){File input(fopen(local.c_str(),"rb"),fclose);require(bool(input),"Open backup for upload");if(!smb){CurlState state;state.file=input.get();state.upload=true;state.max=size;state.phase="Uploading backup";state.path=p;setup(p,state);curl_easy_setopt(curl,CURLOPT_UPLOAD,1L);curl_easy_setopt(curl,CURLOPT_READDATA,input.get());curl_easy_setopt(curl,CURLOPT_INFILESIZE_LARGE,(curl_off_t)size);curl_easy_setopt(curl,CURLOPT_WRITEFUNCTION,+[](char*,size_t a,size_t b,void*){return a*b;});perform(state);return;}auto*f=smb2_open(smb,full(p).c_str(),O_WRONLY|O_CREAT|O_EXCL);require(f,"Create new SMB backup file");std::vector<u8>buf(262144);u64 done=0;try{while(done<size){pump();size_t n=fread(buf.data(),1,std::min<u64>(buf.size(),size-done),input.get());require(n>0,"Short backup read");size_t off=0;while(off<n){int written=smb2_write(smb,f,buf.data()+off,n-off);require(written>0,"SMB write failed");off+=written;}done+=n;vaultTransfer("Uploading backup",p.c_str(),done,size);}require(smb2_fsync(smb,f)==0,"Flush SMB backup");int closed=smb2_close(smb,f);f=nullptr;require(closed==0,"Close SMB backup");}catch(...){if(f)smb2_close(smb,f);throw;}}
 void renameFile(const std::string&from,const std::string&to){if(smb){require(smb2_rename(smb,full(from).c_str(),full(to).c_str())==0,"Commit remote backup");return;}CurlState state;setup("",state);auto u="ftp://"+target.host+":"+std::to_string(target.port)+"/";curl_easy_setopt(curl,CURLOPT_URL,u.c_str());auto*commands=curl_slist_append(nullptr,("RNFR /"+full(from)).c_str());commands=curl_slist_append(commands,("RNTO /"+full(to)).c_str());curl_easy_setopt(curl,CURLOPT_QUOTE,commands);curl_easy_setopt(curl,CURLOPT_NOBODY,1L);try{perform(state);curl_slist_free_all(commands);}catch(...){curl_slist_free_all(commands);throw;}}
 void verify(const std::string&p,const Row&r){CurlState state;state.digest=true;state.max=r.size;sha256ContextCreate(&state.hash);get(p,state);u8 digest[32];sha256ContextGetHash(&state.hash,digest);require(state.count==r.size&&hex(digest,32)==r.hash,"Remote checksum mismatch; backup not committed");}
};
std::vector<Row> inventory(const std::string&root){std::vector<Row>rows;std::vector<std::string>dirs={""};for(size_t i=0;i<dirs.size();i++){pump();DIR*d=opendir((root+"/"+dirs[i]).c_str());require(d,"Inspect local snapshot");try{while(auto*e=readdir(d)){std::string n=e->d_name;if(n=="."||n=="..")continue;auto rel=dirs[i]+n;require(safe(rel),"Unsafe snapshot filename");struct stat st{};require(!lstat((root+"/"+rel).c_str(),&st),"Read snapshot entry");if(S_ISDIR(st.st_mode))dirs.push_back(rel+"/");else{require(S_ISREG(st.st_mode)&&st.st_size>=0&&n!="INCOMPLETE.txt","Snapshot incomplete or contains unsupported files");rows.push_back({rel,"",(u64)st.st_size});}require(rows.size()+dirs.size()<=100000,"Snapshot entry limit");}closedir(d);}catch(...){closedir(d);throw;}}for(auto&r:rows)r.hash=hashFile(root+"/"+r.path,r.size);return rows;}
}
void validateRemoteTarget(const RemoteTarget&t){require(!t.host.empty()&&t.host.size()<254&&t.host.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.-")==std::string::npos,"Use a hostname or IPv4 address without a URL prefix");require(t.port>0&&t.port<=65535,"Invalid server port");require(t.path.empty()||safe(t.path),"Folder must be relative, without '..' or leading slash");require(!t.smb||(!t.share.empty()&&t.share.find_first_of("/\\:\r\n")==std::string::npos),"Enter a single SMB share name");for(auto*s:{&t.user,&t.password,&t.domain})require(s->size()<=255&&s->find_first_of("\r\n")==std::string::npos&&s->find('\0')==std::string::npos,"Invalid credential field");}
RemoteSettings loadRemoteSettings(){RemoteSettings out;try{auto bytes=read("sdmc:/gamevault/storage.cfg",10000);std::istringstream in(std::string(bytes.begin(),bytes.end()));std::string line;std::getline(in,line);require(line=="GVSTORAGE1","Storage configuration version");std::getline(in,line);out.selected=std::stoi(line);require(out.selected>=0&&out.selected<=2,"Storage selection");for(auto*t:{&out.ftp,&out.smb}){for(auto*f:{&t->host,&t->path,&t->user,&t->password,&t->share,&t->domain}){require(bool(std::getline(in,line)),"Storage field missing");*f=unhex(line);}require(bool(std::getline(in,line)),"Port missing");t->port=std::stoul(line);if(t->configured())validateRemoteTarget(*t);}if(out.selected&&!(out.selected==1?out.ftp:out.smb).configured())out.selected=0;}catch(...){return RemoteSettings{};}return out;}
void saveRemoteSettings(const RemoteSettings&s){VaultStorageLease access;std::string text="GVSTORAGE1\n"+std::to_string(s.selected)+"\n";for(auto*t:{&s.ftp,&s.smb}){if(t->configured())validateRemoteTarget(*t);for(auto*f:{&t->host,&t->path,&t->user,&t->password,&t->share,&t->domain})text+=encode(*f)+"\n";text+=std::to_string(t->port)+"\n";}write("sdmc:/gamevault/storage.tmp",text.data(),text.size());struct stat st{};const char*cfg="sdmc:/gamevault/storage.cfg",*old="sdmc:/gamevault/storage.previous";bool had=!stat(cfg,&st);if(had){if(!stat(old,&st))require(!unlink(old),"Remove previous storage settings");require(!rename(cfg,old),"Preserve storage settings");}if(rename("sdmc:/gamevault/storage.tmp",cfg)){if(had)rename(old,cfg);throw std::runtime_error("Save storage settings failed");}}
void testRemoteTarget(const RemoteTarget&t){VaultStorageLease access;Remote remote(t);remote.list("");}
std::vector<std::string> listRemoteBackups(const RemoteTarget&t){VaultStorageLease access;Remote remote(t);std::vector<std::string>out;for(auto&name:remote.list("backups")){pump();if(!backupSnapshotName(name))continue;try{auto text=remote.text("backups/"+name+"/COMPLETE.txt",32*1024*1024);parse(text);out.push_back(name);}catch(const std::exception&e){if(std::string(e.what()).rfind("Cancelled",0)==0)throw;}}return out;}
void uploadRemoteBackup(const RemoteTarget&t,const std::string&local,bool decrypted){VaultStorageLease access;auto rows=inventory(local);auto name=local.substr(local.find_last_of('/')+1);require(backupSnapshotName(name),"Invalid snapshot name");Remote remote(t);struct stat kind{};bool cardOnly=!stat((local+"/cartridge").c_str(),&kind)&&stat((local+"/catalog.bin").c_str(),&kind)&&stat((local+"/saves").c_str(),&kind);std::string category=decrypted?"decrypted":cardOnly?"cartridges":"backups";remote.mkdirs(category);auto existing=remote.list(category);require(std::find(existing.begin(),existing.end(),name)==existing.end(),"Remote snapshot already exists; retained without overwriting");auto root=category+"/"+name;remote.mkdirs(root);std::set<std::string>dirs;for(auto&r:rows){auto slash=r.path.find_last_of('/');if(slash!=std::string::npos)dirs.insert(r.path.substr(0,slash));}for(auto&d:dirs)remote.mkdirs(root+"/"+d);for(auto&r:rows){pump();remote.put(local+"/"+r.path,root+"/"+r.path,r.size);remote.verify(root+"/"+r.path,r);}auto text=manifest(rows);std::string tmp="sdmc:/gamevault/remote-manifest.tmp";write(tmp,text.data(),text.size());remote.put(tmp,root+"/.manifest.tmp",text.size());require(remote.text(root+"/.manifest.tmp",32*1024*1024)==text,"Remote completion record verification failed");remote.renameFile(root+"/.manifest.tmp",root+"/COMPLETE.txt");unlink(tmp.c_str());note("REMOTE_BACKUP_VERIFIED protocol=%s snapshot=%s files=%zu\n",t.smb?"SMB":"FTP",name.c_str(),rows.size());}
std::string downloadRemoteBackup(const RemoteTarget&t,const std::string&name){VaultStorageLease access;require(backupSnapshotName(name),"Invalid remote snapshot name");Remote remote(t);auto rows=parse(remote.text("backups/"+name+"/COMPLETE.txt",32*1024*1024));u64 bytes=0;for(auto&r:rows)bytes+=r.size;FsFileSystem sd{};check(fsOpenSdCardFileSystem(&sd),"SD capacity");s64 free=0;Result rc=fsFsGetFreeSpace(&sd,"/",&free);fsFsClose(&sd);check(rc,"SD free space");require(free>=0&&bytes<=u64(free)&&u64(free)-bytes>=16*1024*1024,"Not enough SD space to stage remote restore");std::string root="sdmc:/gamevault/remote-incoming";mkdir(root.c_str(),0777);root+="/"+name.substr(0,16)+"-"+idstr(armGetSystemTick());fresh(root);for(auto&r:rows){pump();for(size_t at=0;(at=r.path.find('/',at))!=std::string::npos;++at)mkdir((root+"/"+r.path.substr(0,at)).c_str(),0777);File f(fopen((root+"/"+r.path).c_str(),"wb"),fclose);require(bool(f),"Create staging file");CurlState state;state.file=f.get();state.max=r.size;remote.get("backups/"+name+"/"+r.path,state);flush(f.get());require(!fclose(f.release()),"Close staging file");require(hashFile(root+"/"+r.path,r.size)==r.hash,"Downloaded backup checksum mismatch");}struct stat st{};bool game=!stat((root+"/catalog.bin").c_str(),&st),saves=!stat((root+"/saves").c_str(),&st);require(game||saves,"No game or save backup found");if(game)companionValidateImport(root);if(saves)validateImportedSaves(strtoull(name.substr(0,16).c_str(),nullptr,16),root);auto dest="sdmc:/gamevault/backups/"+root.substr(root.find_last_of('/')+1);require(!rename(root.c_str(),dest.c_str()),"Publish verified local restore snapshot");note("REMOTE_IMPORT_VERIFIED snapshot=%s\n",dest.c_str());return dest;}
